package thaumcraft.test;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.wolf.Wolf;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.thaumaturgy.*;
import thaumcraft.aura.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
import static thaumcraft.test.FocusOptionsProbe.Q;

@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class FocusOptionsClient {
    static boolean bounced;static int ticks,stage;static long due;static FocusProjectile shot;static LivingEntity target;static BlockPos denied;static FocalEntity table;
    public static FocusProgram projectile(int speed,int option,String kind){return new FocusProgram("projectile",List.of(new FocusProgram.Effect(kind,1,1)),"none",2,10,1,5,false,List.of(),FocusProgram.PlanSettings.DEFAULT,new FocusProgram.ProjectileSettings(speed,option));}
    static void clearDrops(ServerPlayer p){for(var e:p.level().getEntitiesOfClass(ItemEntity.class,new AABB(Q).inflate(50)))e.discard();}
    static int drops(ServerPlayer p,Item item){return p.level().getEntitiesOfClass(ItemEntity.class,new AABB(Q).inflate(50)).stream().filter(e->e.getItem().is(item)).mapToInt(e->e.getItem().getCount()).sum();}
    static void hit(ServerPlayer p,BlockPos q,FocusProgram.Effect effect){SpellEngine.apply(p,new FocusProgram("bolt",List.of(effect)),new BlockHitResult(Vec3.atCenterOf(q),Direction.UP,q,false));}
    static void mining(ServerPlayer p){
        var l=p.level();var q=Q.east(4).above();var caster=p.getMainHandItem();var saved=caster.copy();clearDrops(p);
        var silk=new FocusProgram.Effect("break",1,1,8,0,true);l.setBlockAndUpdate(q,Blocks.DIAMOND_ORE.defaultBlockState());hit(p,q,silk);check(l.isEmptyBlock(q)&&drops(p,Items.DIAMOND_ORE)==1&&drops(p,Items.DIAMOND)==0,"Silk did not preserve ore");check(p.getMainHandItem()==caster&&ItemStack.matches(caster,saved),"Spell harvest mutated actual caster");clearDrops(p);
        int count=0;for(int i=0;i<24;i++){l.setBlockAndUpdate(q,Blocks.DIAMOND_ORE.defaultBlockState());hit(p,q,new FocusProgram.Effect("break",1,1,8,4,false));}count=drops(p,Items.DIAMOND);check(count>24&&count<=120&&drops(p,Items.DIAMOND_ORE)==0,"Fortune IV did not affect native loot: "+count);clearDrops(p);
        denied=q;l.setBlockAndUpdate(q,Blocks.DIAMOND_ORE.defaultBlockState());hit(p,q,silk);check(l.getBlockState(q).is(Blocks.DIAMOND_ORE)&&drops(p,Items.DIAMOND_ORE)==0&&p.getMainHandItem()==caster,"Cancelled mining changed block, drops or held tool");denied=null;
        l.setBlockAndUpdate(q,Blocks.BEDROCK.defaultBlockState());hit(p,q,silk);check(l.getBlockState(q).is(Blocks.BEDROCK),"Spell broke bedrock");l.setBlockAndUpdate(q,Blocks.CHEST.defaultBlockState());hit(p,q,silk);check(l.getBlockState(q).is(Blocks.CHEST),"Spell broke an inventory");
        l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.DIRT,2));hit(p,q,new FocusProgram.Effect("exchange",1,1,8,0,true));check(l.getBlockState(q).is(Blocks.DIRT)&&drops(p,Items.STONE)==1&&p.getOffhandItem().getCount()==1&&p.getMainHandItem()==caster,"Silk exchange failed native drops, consumption or held preservation");l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);clearDrops(p);Thaumcraft.LOGGER.info("FOCUS_OPTIONS_LOOT_OK: silk ore, Fortune IV batch {}, cancelled break, bedrock/inventory protection, silk exchange and exact held stack preserved",count);
    }
    static void position(ServerPlayer p){p.teleportTo(p.level(),96.5,205,8.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);}
    static FocusProjectile cast(ServerPlayer p,FocusProgram program){position(p);PlanProbe.equip(p,program);AuraManager.addVis(p.level(),p.blockPosition(),1000);float before=AuraManager.get(p.level(),p.blockPosition()).vis();check(p.getMainHandItem().getItem().use(p.level(),p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS,"Native projectile cast failed");check(Math.abs(before-AuraManager.get(p.level(),p.blockPosition()).vis()-program.vis())<.004,"Projectile aura was not paid once");var s=p.level().getEntitiesOfClass(FocusProjectile.class,new AABB(Q).inflate(30)).getFirst();check(Math.abs(s.getDeltaMovement().length()-program.projectile().velocity())<.002,"Configured speed not applied");return s;}
    static void wall(ServerLevel l,boolean fill){for(var q:BlockPos.betweenClosed(Q.offset(-2,0,4),Q.offset(2,3,4)))l.setBlockAndUpdate(q,fill?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("options-client")||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
        if(stage==0){l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.SPAWN_MOBS,false,e.server());l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.SPAWN_PHANTOMS,false,e.server());for(var ent:l.getEntitiesOfClass(LivingEntity.class,new AABB(Q).inflate(55)))if(ent!=p)ent.discard();for(var s:l.getEntitiesOfClass(FocusProjectile.class,new AABB(Q).inflate(55)))s.discard();for(var q:BlockPos.betweenClosed(Q.offset(-8,-1,-5),Q.offset(12,5,24)))l.setBlockAndUpdate(q,q.getY()==204?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());position(p);knowledge(p);p.setGameMode(GameType.SURVIVAL);for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET))p.setItemSlot(slot,ItemStack.EMPTY);p.getFoodData().setFoodLevel(10);p.setHealth(20);PlanProbe.equip(p,projectile(5,1,"earth"));mining(p);wall(l,true);shot=cast(p,projectile(5,1,"earth"));stage=1;due=now+12;return;}
        if(stage==1){if(!bounced&&!shot.isRemoved()&&shot.getDeltaMovement().z<0){bounced=true;var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());shot.saveWithoutId(out);var copy=new FocusProjectile(ThaumaturgyContent.PROJECTILE.get(),l);copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),out.buildResult()));check(copy.program().equals(shot.program())&&copy.expires()==shot.expires()&&copy.getDeltaMovement().equals(shot.getDeltaMovement()),"In-flight projectile snapshot changed settings, deadline or velocity");}if(now<due)return;check(bounced&&l.getBlockState(Q.south(4).above()).is(Blocks.STONE),"Projectile failed to bounce without applying effects");shot.discard();wall(l,false);position(p);target=BatRiftClient.mob(p,p.position().add(2.5,0,8));shot=cast(p,projectile(3,2,"earth"));stage=2;due=now+100;return;}
        if(stage==2){if(!shot.isRemoved()){check(now<due,"Seeking projectile did not reach off-axis enemy");return;}check(target.getHealth()==17,"Seeking projectile lost payload power: "+target.getHealth());target.discard();position(p);var wolf=new Wolf(EntityTypes.WOLF,l);wolf.setPos(p.position().add(2,0,7));wolf.tame(p);wolf.setNoAi(true);wolf.setNoGravity(true);wolf.setHealth(5);l.addFreshEntity(wolf);target=wolf;shot=cast(p,projectile(3,3,"heal"));stage=3;due=now+100;return;}
        if(stage==3){Thaumcraft.LOGGER.info("FOCUS_OPTIONS_FRIEND_TRACE: removed={} at={} velocity={} target={} box={} friendly={} health={}",shot.isRemoved(),shot.position(),shot.getDeltaMovement(),target.position(),target.getBoundingBox(),SpellEngine.friendly(p,target),target.getHealth());if(!shot.isRemoved()){check(now<due,"Friendly projectile failed to acquire owned wolf");return;}check(target.getHealth()==7,"Friendly seeking failed native healing: "+target.getHealth());target.discard();wall(l,true);position(p);target=BatRiftClient.mob(p,p.position().add(2,0,8));shot=cast(p,projectile(3,2,"earth"));stage=4;due=now+20;return;}
        if(stage==4&&now>=due){check(shot.isRemoved()&&target.getHealth()==20,"Seeking projectile crossed a solid wall");target.discard();wall(l,false);position(p);var plan=new FocusProgram("plan",List.of(new FocusProgram.Effect("break",1,1)));PlanProbe.equip(p,plan);p.getMainHandItem().remove(ThaumaturgyContent.PLAN_SELECTION.get());stage=5;due=now+2400;Thaumcraft.LOGGER.info("FOCUS_OPTIONS_PROJECTILES_OK: native speed, bounce, seeking hostile/owned wolf, LOS, complete effects and snapshot; awaiting G, Ctrl+G, G");return;}
        if(stage==5){check(now<due,"Timed out waiting for native resize key");var a=p.getMainHandItem().get(ThaumaturgyContent.PLAN_SELECTION.get());if(a==null)return;check(a.equals(new PlanControls.Selection(0,0,0,0)),"G did not wrap all Plan dimensions");stage=6;Thaumcraft.LOGGER.info("FOCUS_OPTIONS_G_OK");return;}
        if(stage==6){check(now<due,"Timed out waiting for Ctrl+G");var a=p.getMainHandItem().get(ThaumaturgyContent.PLAN_SELECTION.get());if(a.axis()==0)return;check(a.equals(new PlanControls.Selection(0,0,0,1)),"Ctrl+G did not select X");stage=7;Thaumcraft.LOGGER.info("FOCUS_OPTIONS_CTRL_G_OK");return;}
        if(stage==7){check(now<due,"Timed out waiting for X resize");var caster=p.getMainHandItem();var a=caster.get(ThaumaturgyContent.PLAN_SELECTION.get());if(a.x()==0)return;check(a.equals(new PlanControls.Selection(1,0,0,1)),"G changed unselected axes");var program=caster.get(ThaumaturgyContent.FOCUS.get()).get(ThaumaturgyContent.PROGRAM.get());check(PlanControls.effective(caster,program).equals(new FocusProgram.PlanSettings(1,0,0,false))&&program.plan().equals(FocusProgram.PlanSettings.DEFAULT),"Runtime resize changed programmed focus");for(int x=-2;x<=2;x++)l.setBlockAndUpdate(Q.offset(x,1,4),Blocks.STONE.defaultBlockState());AuraManager.addVis(l,p.blockPosition(),1000);check(caster.getItem().use(l,p,InteractionHand.MAIN_HAND)==InteractionResult.SUCCESS,"Resized Plan cast failed");for(int x=-2;x<=2;x++)check(l.getBlockState(Q.offset(x,1,4)).isAir()==(Math.abs(x)<=1),"Server Plan ignored resized dimensions at "+x);for(int x=-2;x<=2;x++)l.setBlockAndUpdate(Q.offset(x,1,4),Blocks.AIR.defaultBlockState());
            p.teleportTo(l,98.5,206,8.5,Set.of(),0,0,true);l.setBlockAndUpdate(Q,ThaumaturgyContent.TABLE.get().defaultBlockState());table=(FocalEntity)l.getBlockEntity(Q);FocusOptionsProbe.costs(p,table);stage=8;Thaumcraft.LOGGER.info("FOCUS_OPTIONS_KEYS_OK: actual G/Ctrl+G packets synchronized bounded axes without recrafting");return;}
        if(stage==8&&!table.working()){check(FocusOptionsProbe.graph().equals(table.inventory.getItem(0).get(ThaumaturgyContent.PROGRAM.get())),"Client-crafted options graph differs");p.setGameMode(GameType.CREATIVE);p.openMenu(table);stage=9;Thaumcraft.LOGGER.info("FOCUS_OPTIONS_CLIENT_OK: native loot, physics, controls, costs and crafted graph complete");}
    }
    @SubscribeEvent public static void impact(net.minecraftforge.event.entity.ProjectileImpactEvent e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").equals("options-client")&&e.getProjectile() instanceof FocusProjectile f&&!f.level().isClientSide())Thaumcraft.LOGGER.info("FOCUS_OPTIONS_IMPACT: stage={} spell={} hit={} at={} entity={}",stage,f.program(),e.getRayTraceResult().getType(),e.getRayTraceResult().getLocation(),e.getRayTraceResult() instanceof EntityHitResult h?h.getEntity().getType():"block");}
    @SubscribeEvent public static void protection(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").equals("options-client")&&e.getPos().equals(denied))e.setResult(net.minecraftforge.common.util.Result.DENY);}
}
